#!/bin/sh
set -u; cd /work/webgpu-poc; O=/tmp/out; mkdir -p $O; log() { echo "$(date -u +%FT%TZ) $*" >> $O/commands.log; }; log "start backend=${BACKEND:-?}"
{ echo "arch: $(uname -m)"; echo "kernel: $(uname -r)"; . /etc/os-release; echo "$PRETTY_NAME"; echo "node $(node -v)"; for p in typegpu unplugin-typegpu vitest webgpu; do echo "$p $(node -p "require(\"./node_modules/$p/package.json\").version")"; done
  dpkg-query -W -f='${Package} ${Version}\n' mesa-vulkan-drivers libllvm20 libvulkan1 2>/dev/null; echo "nproc: $(nproc)"; grep -m1 "model name" /proc/cpuinfo || true; echo "VK_DRIVER_FILES=${VK_DRIVER_FILES:-}"; [ -f /opt/swiftshader/libvk_swiftshader.so ] && sha256sum /opt/swiftshader/libvk_swiftshader.so; } > $O/env.txt 2>&1
dpkg -s mesa-vulkan-drivers >/dev/null 2>&1 && echo "mesa-vulkan-drivers: INSTALLED" >> $O/env.txt || echo "mesa-vulkan-drivers: NOT INSTALLED" >> $O/env.txt
{ for d in /usr/share/vulkan/icd.d /etc/vulkan/icd.d "$HOME/.config/vulkan/icd.d"; do [ -d "$d" ] && ls -A "$d" | sed "s#^#$d/#"; done; } > $O/icd-dirs.raw 2>&1; if [ -s $O/icd-dirs.raw ]; then cp $O/icd-dirs.raw $O/icd-dirs.txt; else echo ICD-DIRS-EMPTY > $O/icd-dirs.txt; fi; rm $O/icd-dirs.raw
VK_LOADER_DEBUG=driver vulkaninfo --summary > /dev/null 2> $O/loader-trace.txt
vulkaninfo --summary > $O/vulkaninfo.txt 2> /dev/null; node third_party/adapter-probe.js > $O/adapter.json 2>&1; node docker/in-container/probe-strict.cjs > $O/adapter-strict.json 2> /dev/null
if [ "${BACKEND:-}" = swiftshader ]; then node docker/in-container/assert-backend.mjs $O > /dev/null 2>&1; A=$?; else if grep -q "llvmpipe" $O/vulkaninfo.txt && ! grep -qi swiftshader $O/vulkaninfo.txt && grep -q "mesa" $O/adapter.json; then A=0; echo "lavapipe identity: llvmpipe in vulkaninfo, mesa in adapter, no SwiftShader" > $O/backend-assert.txt; else A=3; echo "FAIL lavapipe identity" > $O/backend-assert.txt; fi; fi
log "backend assertion exit $A"; if [ $A -ne 0 ]; then echo "backend assertion FAILED; suites not run" > $O/ABORTED.txt; exit 0; fi
for d in bitops vector-fns mul-paths scalar-int integer-mul comptime; do s=$(date +%s); npx vitest run --config investigations/$d/vitest.config.mts --reporter=json --outputFile=$O/$d.vitest.json > $O/$d.stdout 2> $O/$d.stderr; echo $? > $O/$d.exit; log "$d exit $(cat $O/$d.exit) wall $(( $(date +%s)-s ))s"; mkdir -p $O/suites/$d; cp investigations/$d/results.json $O/suites/$d/ 2>/dev/null; cp -R investigations/$d/raw $O/suites/$d/ 2>/dev/null; done
log end
